rule.definition:
a!localVariables(
  local!names:#"SYSTEM_SYSRULES_queryRecordType_v3"(
    recordType: #"urn:appian:record-type:v1:c155a5df-b848-4d0e-b02f-89afb731210d",
    fields: #"SYSTEM_SYSRULES_selectionFields"(
      allFieldsFromRecordType: #"urn:appian:record-type:v1:c155a5df-b848-4d0e-b02f-89afb731210d"
    ),
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "AND",
      filters: {
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:c155a5df-b848-4d0e-b02f-89afb731210d/215a9540-4788-4706-8993-dac4d522d301",
          operator: "in",
          value: ri!stateId
        ),
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:c155a5df-b848-4d0e-b02f-89afb731210d/6005a254-28f5-47b6-9d00-f0e25c605cc2",
          operator: "in",
          value: ri!cityid
        ),
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:c155a5df-b848-4d0e-b02f-89afb731210d/224e70fc-2577-493c-bedb-b7add69cfd46",
          operator: "=",
          value: ri!isActive
        )
      },
      ignoreFiltersWithEmptyValues: true(),
    )
    ,
    pagingInfo: a!defaultValue(
      value: ri!paginginfo,
      default:  #"SYSTEM_SYSRULES_pagingInfo"(
        startIndex: 1,
        batchSize: 5000
      )
    )
  ),
  local!data:index(local!names,"data",null()),
  {
    local!data
  }
)
